package com.metabuild.modules.admin.audit.persistence;
import java.util.*;import org.jooq.*;import org.jooq.impl.DSL;
public final class LoginAuditOutboxWorker {private final DSLContext db;private final String workerId=UUID.randomUUID().toString();public LoginAuditOutboxWorker(DSLContext db){this.db=db;}public int drain(){var rows=db.fetch("with picked as (select id from mb_login_audit_outbox where ((status in ('PENDING','FAILED') and next_attempt_at<=current_timestamp) or (status='PROCESSING' and lease_until<current_timestamp)) order by created_at for update skip locked limit 100) update mb_login_audit_outbox o set status='PROCESSING',worker_id=?,lease_until=current_timestamp+interval '30 seconds',attempts=attempts+1 from picked where o.id=picked.id returning o.*",workerId);for(var row:rows)process(row);return rows.size();}private void process(org.jooq.Record row){UUID id=row.get("id",UUID.class);try{db.transaction(configuration->{DSLContext tx=DSL.using(configuration);tx.execute("insert into mb_login_log(id,user_id,username,success,failure_code,ip_address,user_agent,created_at) values(?,?,?,?,?,?,?,?) on conflict(id) do nothing",id,row.get("user_id",UUID.class),row.get("username",String.class),row.get("success",Boolean.class),row.get("failure_code",String.class),row.get("ip_address"),row.get("user_agent",String.class),row.get("created_at"));tx.execute("update mb_login_audit_outbox set status='DONE',worker_id=null,lease_until=null,processed_at=current_timestamp,last_error=null where id=? and worker_id=?",id,workerId);});}catch(RuntimeException failure){String error=Objects.toString(failure.getMessage(),failure.getClass().getSimpleName());db.execute("update mb_login_audit_outbox set status='FAILED',worker_id=null,lease_until=null,next_attempt_at=current_timestamp+least(interval '5 minutes',interval '1 second'*power(2,least(attempts,8))),last_error=? where id=? and worker_id=?",error.substring(0,Math.min(error.length(),2000)),id,workerId);}}}
